macro_rules! deps {
    () => {
        SmallVec!();
        IntoIter!();
        DropGuard!();
    };
}

macro_rules! spec_traits {
    () => {
        deps!();
        # [cfg (feature = "specialization")] mod spec_traits { use super :: * ; # [doc = " A trait for specializing the implementation of [`from_elem`]."] # [doc = ""] # [doc = " [`from_elem`]: crate::from_elem"] pub (crate) trait SpecFromElem < T > { # [doc = " Creates a `Smallvec` value where `elem` is repeated `n` times."] # [doc = " This will use the inline storage, not the heap."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller must ensure that `n <= Self::inline_size()`."] unsafe fn spec_from_elem (elem : T , n : usize) -> Self ; } impl < T : Clone , const N : usize > SpecFromElem < T > for SmallVec < T , N > { # [inline] default unsafe fn spec_from_elem (elem : T , n : usize) -> Self { unsafe { SmallVec :: from_elem_fallback (elem , n) } } } impl < T : Copy , const N : usize > SpecFromElem < T > for SmallVec < T , N > { unsafe fn spec_from_elem (elem : T , n : usize) -> Self { let mut result = Self :: new () ; if n > 0 { let ptr = result . raw . as_mut_ptr_inline () ; unsafe { for i in 0 .. n { ptr . add (i) . write (elem) ; } } } unsafe { result . set_len (n) ; } result } } # [doc = " A trait for specializing the implementations of [`Extend`] and [`extend_from_slice`]."] # [doc = ""] # [doc = " [`extend_from_slice`]: crate::SmallVec::extend_from_slice"] pub (crate) trait SpecExtend < T , I > { fn spec_extend (& mut self , iter : I) ; } impl < T , I , const N : usize > SpecExtend < T , I > for SmallVec < T , N > where I : Iterator < Item = T > , { # [inline] default fn spec_extend (& mut self , iter : I) { self . extend_fallback (iter) ; } } impl < T , I , const N : usize > SpecExtend < T , I > for SmallVec < T , N > where I : core :: iter :: TrustedLen < Item = T > , { fn spec_extend (& mut self , iter : I) { let (_ , Some (additional)) = iter . size_hint () else { panic ! ("capacity overflow") } ; self . reserve (additional) ; unsafe { let len = self . len () ; let ptr = self . as_mut_ptr () . add (len) ; let mut guard = DropGuard { ptr , len : 0 } ; for x in iter { ptr . add (guard . len) . write (x) ; guard . len += 1 ; } self . set_len (len + guard . len) ; core :: mem :: forget (guard) ; } } } impl < T , const N : usize , const M : usize > SpecExtend < T , IntoIter < T , M > > for SmallVec < T , N > { fn spec_extend (& mut self , mut iter : IntoIter < T , M >) { let slice = iter . as_slice () ; let len = slice . len () ; let old_len = self . len () ; self . reserve (len) ; unsafe { let dst = self . as_mut_ptr () . add (old_len) ; let src = slice . as_ptr () ; copy_nonoverlapping (src , dst , len) ; } unsafe { self . set_len (old_len + len) ; } iter . begin = iter . end . value (Self :: is_zst ()) ; } } impl < 'a , T : 'a , const N : usize , I > SpecExtend < & 'a T , I > for SmallVec < T , N > where I : Iterator < Item = & 'a T > , T : Clone , { # [inline] default fn spec_extend (& mut self , iterator : I) { self . spec_extend (iterator . cloned ()) } } impl < 'a , T : 'a , const N : usize > SpecExtend < & 'a T , core :: slice :: Iter < 'a , T > > for SmallVec < T , N > where T : Copy , { fn spec_extend (& mut self , iter : core :: slice :: Iter < 'a , T >) { let slice = iter . as_slice () ; let len = slice . len () ; let old_len = self . len () ; self . reserve (len) ; unsafe { let dst = self . as_mut_ptr () . add (old_len) ; let src = slice . as_ptr () ; copy_nonoverlapping (src , dst , len) ; } unsafe { self . set_len (old_len + len) ; } } } # [doc = " A trait for specializing the implementation of [`extend_from_within`]."] # [doc = ""] # [doc = " [`extend_from_within`]: crate::SmallVec::extend_from_within"] pub (crate) trait SpecExtendFromWithin < T > { # [doc = " Main worker for [`extend_from_within`]."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " * The length of the vector is larger than or equal to `src.len()`."] # [doc = " * The spare capacity of the vector is larger than or equal to `src.len()`."] # [doc = ""] # [doc = " [`extend_from_within`]: SmallVec::extend_from_within"] unsafe fn spec_extend_from_within (& mut self , src : core :: ops :: Range < usize >) ; } impl < T : Clone , const N : usize > SpecExtendFromWithin < T > for SmallVec < T , N > { default unsafe fn spec_extend_from_within (& mut self , src : core :: ops :: Range < usize >) { unsafe { self . extend_from_within_fallback (src) ; } } } impl < T : Copy , const N : usize > SpecExtendFromWithin < T > for SmallVec < T , N > { unsafe fn spec_extend_from_within (& mut self , src : core :: ops :: Range < usize >) { let old_len = self . len () ; let start = src . start ; let len = src . len () ; unsafe { let ptr = self . as_mut_ptr () ; let dst = ptr . add (old_len) ; let src = ptr . add (start) ; copy_nonoverlapping (src , dst , len) ; } unsafe { self . set_len (old_len + len) ; } } } # [doc = " A trait for specializing the implementation of [`FromIterator`]."] # [doc = ""] # [doc = " [`clone_from`]: Clone::clone_from"] pub (crate) trait SpecFromIterator < T , I > { fn spec_from_iter (iter : I) -> Self ; } impl < T , I , const N : usize > SpecFromIterator < T , I > for SmallVec < T , N > where I : Iterator < Item = T > , { # [inline] default fn spec_from_iter (iter : I) -> Self { Self :: from_iter_fallback (iter) } } impl < T , I , const N : usize > SpecFromIterator < T , I > for SmallVec < T , N > where I : core :: iter :: TrustedLen < Item = T > , { fn spec_from_iter (iter : I) -> Self { let mut v = match iter . size_hint () { (_ , Some (upper)) => SmallVec :: with_capacity (upper) , _ => panic ! ("capacity overflow") , } ; v . spec_extend (iter) ; v } } # [doc = " A trait for specializing the implementation of [`clone_from`]."] # [doc = ""] # [doc = " [`clone_from`]: Clone::clone_from"] pub (crate) trait SpecCloneFrom < T > { fn spec_clone_from (& mut self , source : & [T]) ; } impl < T : Clone , const N : usize > SpecCloneFrom < T > for SmallVec < T , N > { # [inline] default fn spec_clone_from (& mut self , source : & [T]) { self . clone_from_fallback (source) ; } } impl < T : Copy , const N : usize > SpecCloneFrom < T > for SmallVec < T , N > { fn spec_clone_from (& mut self , source : & [T]) { self . clear () ; self . extend_from_slice (source) ; } } # [doc = " A trait for specializing the implementation of [`From`]"] # [doc = " with the source type being slices."] pub (crate) trait SpecFromSlice < T > { # [doc = " Creates a `SmallVec` value based on the contents of `slice`."] # [doc = " This will use the inline storage, not the heap."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller must ensure that `slice.len() <= Self::inline_size()`."] unsafe fn spec_from (slice : & [T]) -> Self ; } impl < T : Clone , const N : usize > SpecFromSlice < T > for SmallVec < T , N > { default unsafe fn spec_from (slice : & [T]) -> Self { unsafe { Self :: from_slice_fallback (slice) } } } impl < T : Copy , const N : usize > SpecFromSlice < T > for SmallVec < T , N > { unsafe fn spec_from (slice : & [T]) -> Self { let mut v = Self :: new () ; let src = slice . as_ptr () ; let len = slice . len () ; let dst = v . as_mut_ptr () ; unsafe { copy_nonoverlapping (src , dst , len) ; } unsafe { v . set_len (len) ; } v } } }
    };
}

spec_traits!()